package com.openggf.game.soniccd;
import com.openggf.game.save.*;import com.openggf.game.session.SessionManager;import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.parallel.Isolated;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Explicitly constructed HMove physical row in authentic ordinary World; no natural reach claim. */
@Isolated class TestCdOriginalTtHMoveWorld extends TestCdOriginalR11LoadingWorld {
 @Test void constructedCurrentHMoveUsesOriginalDataSharedSolidAndFullCourseReplay()throws Exception {var source=TestCdOriginalBootPrefix.source();var saves=new SaveManager(root);var profile=CdSaveProfile.fromTemplate(source.initialSaveAssets().orElseThrow()).withPatch(new CdIpxProgress.SavePatch(OptionalInt.of(0x200),OptionalInt.of(4),OptionalInt.of(0x90),OptionalInt.of(0),OptionalInt.of(0x35),OptionalInt.of(2),OptionalInt.of(3)));saves.writeSlot("scd",1,profile.encode());var attempt=SonicCdGameModule.prepareSelectedProfile(source,saves,1,SonicCdGameModule.ProfileEntry.LOAD_GAME,0);var m=attempt.module().orElseThrow();try(var boot=boot()){var loop=boot.bootSonicCdSelectedProfile(source,attempt);for(int n=0;n<256&&m.originalR11LoadingPrefix().main().levelStartedByte()!=1;n++)step(loop,0);step(loop,0);var frame=m.originalR11EntryFrame();var world=m.originalR11WorldImage().orElseThrow();var binding=field(field(m,"r11World"),"binding");var placement=(CdObjectPlacementRuntime)field(binding,"placement");var old=placement.pool().state(127);assertEquals(0,old.id(),"Constructed fixture requires one actually free physical row");var p=frame.state().motion();var row=old.moveByte(CdObjectState.ByteField.ID,0x24).moveByte(CdObjectState.ByteField.SUBTYPE,1).moveByte(CdObjectState.ByteField.ROUTINE,0).moveWord(CdObjectState.WordField.X,p.centreX16_16()>>>16).moveWord(CdObjectState.WordField.Y,((p.centreY16_16()>>>16)+96)&65535);placement.pool().write(row);var registry=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=registry.capture();var course=registry.captureCourse();step(loop,0);assertFalse(frame.closed());var after=placement.pool().state(127);assertEquals(0x24,after.id());assertEquals(2,after.routine());assertEquals(0x20C376,after.longBits(CdObjectState.LongField.MAPPINGS));var expected=image(m);for(boolean c:new boolean[]{false,true}){if(c)registry.restoreCourse(course);else registry.restore(full);step(loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(m));}}}
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingPrefix(),m.originalR11LoadingImage(),m.originalR11FirstLoad(),m.originalLoadingWaterImage(),m.originalLoadingWaterPalette(),m.originalR11WorldImage(),m.programServicesState(),m.selectedProfileState());}
 private static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
}
